            status: true,
            teacherScore: true,
            teacherFeedback: true,
            aiPreGradeJson: true,
            versionId: true,
            content: true,
            submittedAt: true,
          },
        },
      },
      orderBy: { createdAt: 'desc' },
    });

    return NextResponse.json({
      assignments: assignments.map((a) => {
        const studentSub = a.submissions[0];
