import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';
import { getCurrentUser } from '@/lib/auth';

export async function POST(request: Request) {
  try {
    const user = await getCurrentUser();
    if (!user) {
      return NextResponse.json({ error: 'Chưa đăng nhập' }, { status: 401 });
    }
    if (process.env.VERCEL === '1') {
      return NextResponse.json({ error: 'Tải ghi âm đang chờ kết nối kho lưu trữ trực tuyến.' }, { status: 503 });
    }

    const formData = await request.formData();
    const file = formData.get('audio') as File | null;

    if (!file) {
      return NextResponse.json(
        { error: 'Không tìm thấy tệp âm thanh trong yêu cầu tải lên.' },
        { status: 400 }
      );
    }

    if (!['audio/webm','audio/mp4','audio/ogg','audio/wav','audio/x-wav','audio/mpeg'].includes(file.type.split(';')[0])) return NextResponse.json({error:'Định dạng âm thanh không được hỗ trợ.'},{status:400});
    // 1. Kiểm tra kích thước tệp âm thanh
    if (file.size < 500) {
      return NextResponse.json(
        {
          error: 'Bản ghi âm rỗng hoặc không có dữ liệu âm thanh (kích thước nhỏ hơn 500 bytes). Vui lòng ghi âm lại.',
          code: 'AUDIO_EMPTY',
        },
        { status: 400 }
      );
    }

    const MAX_SIZE = 20 * 1024 * 1024; // 20MB
    if (file.size > MAX_SIZE) {
      return NextResponse.json(
        {
          error: 'Tệp âm thanh vượt quá giới hạn dung lượng 20MB.',
          code: 'AUDIO_TOO_LARGE',
        },
        { status: 400 }
      );
    }

    // 2. Chuẩn bị thư mục lưu trữ
    const uploadDir = path.join(process.cwd(), 'public/uploads/audio');
    if (!fs.existsSync(uploadDir)) {
      fs.mkdirSync(uploadDir, { recursive: true });
    }

    // 3. Đặt tên tệp duy nhất
    const ext = file.type.includes('ogg') ? 'ogg' : file.type.includes('mp4') ? 'mp4' : file.type.includes('wav') ? 'wav' : file.type.includes('mpeg') || file.type.includes('mp3') ? 'mp3' : 'webm';
    const filename = `speaking-${Date.now()}-${Math.random().toString(36).substring(2, 8)}.${ext}`;
    const filePath = path.join(uploadDir, filename);

    // 4. Lưu buffer vào ổ đĩa
    const arrayBuffer = await file.arrayBuffer();
    const buffer = Buffer.from(arrayBuffer);
    fs.writeFileSync(filePath, buffer);

    const publicUrl = `/uploads/audio/${filename}`;

    return NextResponse.json({
      success: true,
      url: publicUrl,
      size: file.size,
      mimeType: file.type || `audio/${ext}`,
      filename,
    });
  } catch (error: any) {
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}

